package com.portfolio.fraud.entity;
import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="users") public class User { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false,unique=true) private String email; @Column(name="password_hash",nullable=false) private String passwordHash; @Column(name="full_name",nullable=false) private String fullName; @Enumerated(EnumType.STRING) @Column(nullable=false) private Role role=Role.CUSTOMER; @Column(name="created_at",nullable=false,updatable=false) private Instant createdAt=Instant.now(); protected User(){} public User(String e,String p,String n){email=e;passwordHash=p;fullName=n;} public static User developmentAdmin(String email,String hash){User user=new User(email,hash,"Development Admin");user.role=Role.ADMIN;return user;} public Long getId(){return id;} public String getEmail(){return email;} public String getPasswordHash(){return passwordHash;} public String getFullName(){return fullName;} public Role getRole(){return role;} }
